#!/usr/bin/env bash
# AI generated by: Claude Code / claude-opus-5-5
# Prompt: "i changed my mind could you host in on the t3-exec vm, its should be accessible through tailscale"
# Changes: Repeatable deploy – sync sources to the VM, build there, install to /opt/table-maker,
#          (re)start the systemd service and publish it on the tailnet with Tailscale Serve.
#
# AI generated by: Claude Code / claude-opus-5-5
# Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
# Changes: Ships a commit (git archive HEAD, refuses a dirty tree without --allow-dirty) into a per-commit build dir
#          under ~/.cache (never the checkout), installs it as /opt/table-maker/releases/<sha> behind a `current`
#          symlink (REVISION file, `previous` kept for --rollback), backs up the SQLite DB before every restart
#          (last 10 kept), checks Node >= 22.13 before restarting and serializes deploys with a lock.
#
# Usage: deploy/deploy.sh [--allow-dirty] [ssh-host]              build HEAD and switch to it (default host: t3-exec)
#        deploy/deploy.sh --rollback [--restore-db] [ssh-host]    switch back to the previous release
#
#   --allow-dirty  deploy although the working tree has uncommitted changes (they are NOT shipped – only HEAD is)
#   --rollback     swap `current` and `previous`; refuses when the current release migrated the database,
#                  unless --restore-db is given
#   --restore-db   with --rollback: also put back the database backup taken right before the current release was
#                  activated (changes made since then are lost, but a fresh backup is taken first)
#
# On the VM: releases in /opt/table-maker/releases/<sha12> (last 5 kept), database backups in
# /var/backups/table-maker/<UTC time>-<label>/table-maker.db (last 10 kept).
set -euo pipefail

usage() { sed -n '/^# Usage:/,/^# On the VM/p' "$0" | sed '$d; s/^# \{0,1\}//'; }

MODE=deploy
ALLOW_DIRTY=0
RESTORE_DB=0
HOST=
while (($#)); do
  case "$1" in
    --allow-dirty) ALLOW_DIRTY=1 ;;
    --rollback) MODE=rollback ;;
    --restore-db) RESTORE_DB=1 ;;
    -h | --help) usage; exit 0 ;;
    -*) echo "Unknown option: $1" >&2; usage >&2; exit 2 ;;
    *)
      [[ -z "$HOST" ]] || { echo "Only one ssh host may be given" >&2; exit 2; }
      HOST="$1"
      ;;
  esac
  shift
done
HOST="${HOST:-t3-exec}"
if ((RESTORE_DB)) && [[ "$MODE" != rollback ]]; then
  echo "--restore-db only makes sense with --rollback" >&2
  exit 2
fi

# Everything below runs on the VM (bash -s). It is wrapped in functions and only started by the last line, so bash
# has read the whole script before any command could consume stdin.
remote_script() {
  cat <<'REMOTE'
set -euo pipefail
shopt -s inherit_errexit   # errexit also inside $(backup_db …)

APP_ROOT=/opt/table-maker
RELEASES=$APP_ROOT/releases
CURRENT=$APP_ROOT/current
PREVIOUS=$APP_ROOT/previous
BACKUPS=/var/backups/table-maker
DB=/var/lib/table-maker/table-maker.db   # StateDirectory of the DynamicUser service (-> /var/lib/private/table-maker)
NODE=/usr/local/bin/node                 # same absolute path as ExecStart= in table-maker.service
UNIT=table-maker.service
PORT=4310
BUILD_ROOT="$HOME/.cache/table-maker-build"
KEEP_RELEASES=5
KEEP_BACKUPS=10
STOPPED=0

# Whatever fails after the service was stopped, never leave it down: start whatever `current` points at.
trap 'if ((STOPPED)) && ! systemctl is-active -q "$UNIT"; then sudo systemctl start "$UNIT" || true; fi' EXIT

log() { echo "==> $*" >&2; }
die() { echo "error: $*" >&2; exit 1; }

# Same check as ExecStartPre= in the unit: node:sqlite is unflagged from Node 22.13 on.
NODE_CHECK="const [a, b] = process.versions.node.split('.').map(Number); if (a < 22 || (a === 22 && b < 13) || !process.getBuiltinModule('node:sqlite')) { console.error('table-maker: need Node >= 22.13 with node:sqlite, got ' + process.version); process.exit(1) }"
check_node() {
  [[ -x "$NODE" ]] || die "$NODE not found"
  "$NODE" --no-warnings -e "$NODE_CHECK" || die "$NODE is too old"
}

rev_of() { sudo cat "$1/REVISION" 2>/dev/null || echo unknown; }

# Stops nothing by itself – call with the service stopped so the copy is consistent. Copies the DB (+ -wal/-shm),
# folds the WAL into the copy, checks it and records its schema version. Only the copy is ever opened, never the
# live file (opening that as root could leave root-owned -wal/-shm files the service cannot write).
# Prints the backup dir (empty when there is no database yet).
backup_db() {
  local label="$1" dir f
  if ! sudo test -f "$DB"; then
    log "No database at $DB yet, nothing to back up"
    return 0
  fi
  dir="$BACKUPS/$(date -u +%Y%m%dT%H%M%SZ)-$label"
  sudo install -d -m 700 "$BACKUPS" "$dir"
  for f in "$DB" "$DB-wal" "$DB-shm"; do
    if sudo test -f "$f"; then sudo cp -p "$f" "$dir/"; fi
  done
  sudo "$NODE" --no-warnings -e "
    const { DatabaseSync } = require('node:sqlite')
    const db = new DatabaseSync(process.argv[1])
    db.exec('PRAGMA wal_checkpoint(TRUNCATE); PRAGMA journal_mode = DELETE;')
    const ok = db.prepare('PRAGMA integrity_check').get().integrity_check
    if (ok !== 'ok') { console.error('integrity_check: ' + ok); process.exit(1) }
    console.log(db.prepare('PRAGMA user_version').get().user_version)
    db.close()
  " "$dir/table-maker.db" | sudo tee "$dir/SCHEMA_VERSION" >/dev/null || die "backup in $dir failed its integrity check"
  log "Database backed up to $dir (schema v$(sudo cat "$dir/SCHEMA_VERSION"))"
  echo "$dir"
}

restore_db() {
  local src="$1/table-maker.db" owner
  sudo test -f "$src" || die "backup $src not found"
  # Keep the owner of the state dir so the dynamic user can open the file (UMask=0077 -> 0600).
  owner=$(sudo stat -c %u:%g "$(sudo readlink -f "$(dirname "$DB")")")
  sudo rm -f "$DB-wal" "$DB-shm"
  sudo install -m 600 -o "${owner%:*}" -g "${owner#*:}" "$src" "$DB"
  log "Database restored from $1"
}

# Atomic symlink switch.
point() { sudo ln -sfn "$2" "$1.tmp" && sudo mv -T "$1.tmp" "$1"; }

stop_service() {
  STOPPED=1
  sudo systemctl stop "$UNIT" 2>/dev/null || true
}

# One-time move of the pre-release layout (output copied straight into /opt/table-maker) into releases/legacy.
# Runs with the service stopped – Nitro loads route chunks lazily from server/.
migrate_layout() {
  if [[ ! -L "$CURRENT" ]] && sudo test -d "$APP_ROOT/server"; then
    log "Moving the old flat install to $RELEASES/legacy"
    sudo install -d -m 755 "$RELEASES/legacy"
    for f in server public nitro.json; do
      if sudo test -e "$APP_ROOT/$f"; then sudo mv "$APP_ROOT/$f" "$RELEASES/legacy/"; fi
    done
    echo "legacy (installed before releases were tracked)" | sudo tee "$RELEASES/legacy/REVISION" >/dev/null
    point "$CURRENT" "$RELEASES/legacy"
  fi
}

start_and_check() {
  sudo systemctl daemon-reload
  sudo systemctl enable "$UNIT" >/dev/null
  sudo systemctl restart "$UNIT"
  for _ in $(seq 1 30); do
    curl -fs -o /dev/null "http://127.0.0.1:$PORT/" && break
    sleep 0.5
  done
  if ! curl -fsS -o /dev/null "http://127.0.0.1:$PORT/"; then
    sudo journalctl -u "$UNIT" -n 50 --no-pager
    die "service did not come up on 127.0.0.1:$PORT (deploy/deploy.sh --rollback switches back)"
  fi
  sudo tailscale serve --bg --https="$PORT" "http://127.0.0.1:$PORT" >/dev/null
  local name
  name=$(tailscale status --json | python3 -c 'import json,sys; print(json.load(sys.stdin)["Self"]["DNSName"].rstrip("."))' 2>/dev/null || echo '<tailnet-host>')
  STOPPED=0
  log "Running $(rev_of "$CURRENT") at https://$name:$PORT/ (tailnet only)"
}

prune() {
  local keep_cur keep_prev d n=0 refs
  keep_cur=$(readlink -f "$CURRENT" 2>/dev/null || true)
  keep_prev=$(readlink -f "$PREVIOUS" 2>/dev/null || true)
  while read -r d; do
    [[ "$d" == "$keep_cur" || "$d" == "$keep_prev" ]] && continue
    n=$((n + 1))
    if ((n > KEEP_RELEASES - 2)); then log "Removing old release $d"; sudo rm -rf -- "$d"; fi
  done < <(sudo find "$RELEASES" -mindepth 1 -maxdepth 1 -type d ! -name '.*' -printf '%T@ %p\n' | sort -rn | cut -d' ' -f2-)

  # Backups referenced by current/previous (needed by --rollback --restore-db) are never pruned.
  refs=$(sudo cat "$keep_cur/PRE_DEPLOY_BACKUP" "$keep_prev/PRE_DEPLOY_BACKUP" 2>/dev/null || true)
  n=0
  while read -r d; do
    [[ -n "$d" ]] || continue
    grep -qxF -- "$d" <<<"$refs" && continue
    n=$((n + 1))
    if ((n > KEEP_BACKUPS)); then sudo rm -rf -- "$d"; fi
  done < <(sudo find "$BACKUPS" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | sort -r)

  find "$BUILD_ROOT" -mindepth 1 -maxdepth 1 -type d ! -name "${1:-none}" -exec rm -rf -- {} + 2>/dev/null || true
}

do_deploy() {
  local sha="$1" short="${1:0:12}" build release cur backup
  build="$BUILD_ROOT/$short"
  release="$RELEASES/$short"
  [[ -d "$build" ]] || die "no uploaded sources in $build"
  grep -qF "$CURRENT/server/index.mjs" "$build/deploy/$UNIT" ||
    die "deploy/$UNIT of $short predates the releases layout (ExecStart must use $CURRENT); deploy a newer commit"

  sudo install -d -m 755 "$RELEASES"
  if sudo test -f "$release/REVISION"; then
    log "Release $short already built, reusing it"
    sudo touch "$release"
  else
    log "Building $sha in $build"
    cd "$build"
    npm ci --no-audit --no-fund </dev/null
    npm run typecheck </dev/null
    npm test </dev/null
    npm run build </dev/null
    sudo rm -rf "$RELEASES"/.tmp-*
    sudo cp -a .output "$RELEASES/.tmp-$short"
    sudo install -m 644 deploy/table-maker.service "$RELEASES/.tmp-$short/$UNIT"
    echo "$sha" | sudo tee "$RELEASES/.tmp-$short/REVISION" >/dev/null
    sudo chown -R root:root "$RELEASES/.tmp-$short"
    sudo mv -T "$RELEASES/.tmp-$short" "$release"
  fi

  check_node
  log "Stopping $UNIT"
  stop_service
  migrate_layout
  cur=$(readlink -f "$CURRENT" 2>/dev/null || true)
  [[ -z "$cur" ]] || log "Was running $(rev_of "$cur")"
  backup=$(backup_db "before-$short")

  if [[ "$cur" != "$release" ]]; then
    echo "$backup" | sudo tee "$release/PRE_DEPLOY_BACKUP" >/dev/null
    if [[ -n "$cur" ]]; then point "$PREVIOUS" "$cur"; fi
    point "$CURRENT" "$release"
  fi
  sudo install -m 644 "$release/$UNIT" "/etc/systemd/system/$UNIT"
  start_and_check
  prune "$short"
}

do_rollback() {
  local restore="$1" cur prev pre safety live_v pre_v
  [[ -L "$PREVIOUS" ]] || die "no previous release to roll back to"
  cur=$(readlink -f "$CURRENT")
  prev=$(readlink -f "$PREVIOUS")
  sudo test -d "$prev/server" || die "previous release $prev is missing"
  log "Rolling back $(rev_of "$cur") -> $(rev_of "$prev")"

  check_node
  stop_service
  safety=$(backup_db "rollback-from-$(basename "$cur")")
  pre=$(sudo cat "$cur/PRE_DEPLOY_BACKUP" 2>/dev/null || true)

  if ((restore)); then
    [[ -n "$pre" ]] || die "no pre-deploy backup recorded for $cur (nothing changed)"
    restore_db "$pre"
  elif [[ -n "$safety" && -n "$pre" ]]; then
    live_v=$(sudo cat "$safety/SCHEMA_VERSION")
    pre_v=$(sudo cat "$pre/SCHEMA_VERSION" 2>/dev/null || echo "$live_v")
    if ((live_v > pre_v)); then
      die "$(rev_of "$cur") migrated the database v$pre_v -> v$live_v, which the previous release may not read.
Rerun with --rollback --restore-db to also restore $pre (changes since that deploy are lost; current state saved in $safety)."
    fi
  fi

  point "$CURRENT" "$prev"
  point "$PREVIOUS" "$cur"
  if sudo test -f "$prev/$UNIT"; then sudo install -m 644 "$prev/$UNIT" "/etc/systemd/system/$UNIT"; fi
  start_and_check
}

main() {
  mkdir -p "$BUILD_ROOT"
  exec 9>"$BUILD_ROOT/.lock"
  flock -n 9 || die "another deploy is running"
  case "$1" in
    deploy) do_deploy "$2" ;;
    rollback) do_rollback "$2" ;;
    *) die "unknown mode $1" ;;
  esac
}

main "$@"
REMOTE
}

if [[ "$MODE" == rollback ]]; then
  remote_script | ssh "$HOST" bash -s -- rollback "$RESTORE_DB"
  exit 0
fi

APP_DIR="$(cd "$(dirname "$0")/.." && pwd)"
cd "$APP_DIR"
SHA=$(git rev-parse --verify HEAD)
SHORT=${SHA:0:12}

if [[ -n "$(git status --porcelain)" ]]; then
  if ((ALLOW_DIRTY)); then
    echo "warning: uncommitted changes are NOT deployed – shipping HEAD only" >&2
  else
    git status --short >&2
    echo "Working tree is dirty; commit first or pass --allow-dirty (ships HEAD without these changes)." >&2
    exit 1
  fi
fi

# The payload is exactly the tracked files of HEAD; refuse if a database, .env or dependencies were ever committed.
if git ls-tree -r --name-only HEAD | grep -E '(^|/)(node_modules|\.output)/|(^|/)\.env($|\.)|^data/|\.(db|sqlite3?)(-wal|-shm|-journal)?$|\.local$'; then
  echo "Refusing to deploy: the files above must not be shipped (remove them from git)." >&2
  exit 1
fi

echo "==> Deploying $SHA ($(git log -1 --format=%s HEAD)) to $HOST"
# Per-commit build dir under ~/.cache on the VM – never ~/build/table-maker, which may be this very checkout.
git archive --format=tar HEAD |
  ssh "$HOST" "d=\"\$HOME/.cache/table-maker-build/$SHORT\" && rm -rf \"\$d\" && mkdir -p \"\$d\" && tar -x -C \"\$d\""
remote_script | ssh "$HOST" bash -s -- deploy "$SHA"
